package org.apache.commons.lang.text;

import junit.framework.TestCase;

public class AgentBRT_Lang_61_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        StrBuilder strBuilder = new StrBuilder("hello");
        // Attempt to find a string "world" starting from index 5
        // "world" is longer than the remaining buffer from index 5 (empty)
        int result = strBuilder.indexOf("world", 5);
        // Expecting -1 because "world" cannot be found in the remaining buffer
        assertEquals(-1, result);
    }
}

