package org.apache.commons.lang.text;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Lang_61_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        StrBuilder strBuilder = new StrBuilder("hello");
        // Attempt to find a string "world" starting from index 3
        // "world" is longer than the remaining buffer from index 3 ("lo")
        int result = strBuilder.indexOf("world", 3);
        // Expecting -1 because "world" cannot be found in the remaining buffer
        assertEquals(-1, result);
    }
}

